export const i18n = createI18n({
    legacy: false,
    locale: localStorage.getItem('locale') || 'zh-CN',
    fallbackLocale: 'en',
    messages
})

// Screen readers use the document language, which must follow the active locale.
export const syncDocumentLanguage = (locale: string) => {
    if (typeof document === 'undefined') return
    document.documentElement.lang = locale
}

syncDocumentLanguage(String(i18n.global.locale.value))

// Persist locale and update the visible language and document language together.
export const setLocale = (locale: string) => {
    i18n.global.locale.value = locale as typeof i18n.global.locale.value
    localStorage.setItem('locale', locale)
    syncDocumentLanguage(locale)
}

export default i18n
